INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_admin', 'es-ES', 'El indicador de administrador de identidad permite al usuario acceder al sistema IDP para realizar cambios de nivel administrativo, pero no otorga derechos de administración a esta aplicación. Para otorgar accesos de administración a la aplicación, establezca los roles aplicativos.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_admin_title', 'es-ES', 'No es un rol administrativo', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_verified', 'es-ES', 'Indica si el proceso de verificación de identidad se ha completado con éxito. Puede depender de un proceso KYC u otro tipo de verificación.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.is_verified_title', 'es-ES', 'Verificación de la identidad', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO system.translations (key, language, value, created_at, created_by, updated_at, updated_by, version) VALUES ('system.entities.user_profile.hints.email_verified', 'es-ES', 'Indica si el email ha sido verificado, generalmente mediante un enlace enviado a la bandeja de entrada que se supone que solo puede ser leído por el usuario cuyo perfil estamos configurando.', '2026-05-18T14:27:00Z', 'initial-setup', '2026-05-18T14:27:00Z', 'initial-setup', 1) ON CONFLICT (key, language) WHERE deleted_at IS NULL DO NOTHING;
